CREATE TABLE IF NOT EXISTS companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,domain VARCHAR(253) NOT NULL UNIQUE,country VARCHAR(100) NOT NULL,industry VARCHAR(120) NOT NULL DEFAULT '',source_url VARCHAR(1000) NOT NULL DEFAULT '',hiring_signal TEXT NULL,score TINYINT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'research',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(country),INDEX(status));
CREATE TABLE IF NOT EXISTS contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,full_name VARCHAR(255) NOT NULL DEFAULT '',role_title VARCHAR(150) NOT NULL DEFAULT '',permission_status ENUM('unknown','confirmed','revoked') NOT NULL DEFAULT 'unknown',permission_basis VARCHAR(150) NOT NULL DEFAULT '',permission_evidence TEXT NULL,permission_at DATETIME NULL,validation_status VARCHAR(30) NOT NULL DEFAULT 'unverified',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS proposals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,contact_id BIGINT UNSIGNED NOT NULL,subject VARCHAR(255) NOT NULL,body MEDIUMTEXT NOT NULL,status ENUM('draft','approved','sent','failed','cancelled') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_at DATETIME NULL,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(contact_id) REFERENCES contacts(id));
CREATE TABLE IF NOT EXISTS mail_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,proposal_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(40) NOT NULL,detail TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proposal_id) REFERENCES proposals(id));
CREATE TABLE IF NOT EXISTS discovery_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,market VARCHAR(100) NOT NULL,industry VARCHAR(100) NOT NULL,found_count INT NOT NULL DEFAULT 0,added_count INT NOT NULL DEFAULT 0,error_message TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppression(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,reason VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,note TEXT NOT NULL,next_action DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,action VARCHAR(100) NOT NULL,detail TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
